2	///
3	/// Note that some cases are superset of others.
4	/// For example, `Case::Camel` includes `Case::Lower`.
5	/// See [Case::is_compatible_with] for more details.
6	#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash)]
7	pub enum Case {
8	    /// Unknown case
9	    #[default]
10	    Unknown,
11	    /// camelCase
12	    Camel,
13	    // CONSTANT_CASE
14	    Constant,
15	    /// kebab-case
16	    Kebab,
17	    /// lowercase
18	    Lower,
19	    /// A, B1, C42
20	    NumberableCapital,
21	    /// PascalCase
22	    Pascal,
23	    /// snake_case
24	    Snake,
25	    /// Alphanumeric Characters that cannot be in lowercase or uppercase (numbers and syllabary)
26	    Uni,
27	    /// UPPERCASE
28	    Upper,
