77	    pub fn identify(value: &str, strict: bool) -> Case {
78	        let mut chars = value.chars();
79	        let Some(first_char) = chars.next() else {
80	            return Case::Unknown;
81	        };
82	        let mut result = if first_char.is_uppercase() {
83	            Case::NumberableCapital
84	        } else if first_char.is_lowercase() {
85	            Case::Lower
86	        } else if first_char.is_alphanumeric() {
87	            Case::Uni
88	        } else {
89	            return Case::Unknown;
90	        };
91	        let mut previous_char = first_char;
92	        let mut has_consecutive_uppercase = false;
93	        for current_char in chars {
94	            result = match current_char {
95	                '-' => match result {
96	                    Case::Kebab | Case::Lower => Case::Kebab,
97	                    _ => return Case::Unknown,
98	                },
99	                '_' => match result {
100	                    Case::Constant | Case::NumberableCapital | Case::Upper => Case::Constant,
101	                    Case::Lower | Case::Snake => Case::Snake,
102	                    _ => return Case::Unknown,
103	                },
104	                _ if current_char.is_uppercase() => {
105	                    has_consecutive_uppercase |= previous_char.is_uppercase();
106	                    match result {
107	                        Case::Camel | Case::Pascal if strict && has_consecutive_uppercase => {
108	                            return Case::Unknown
109	                        }
110	                        Case::Camel | Case::Constant | Case::Pascal => result,
111	                        Case::Lower => Case::Camel,
112	                        Case::NumberableCapital | Case::Upper => Case::Upper,
113	                        _ => return Case::Unknown,
114	                    }
115	                }
116	                _ if current_char.is_lowercase() => match result {
117	                    Case::Camel | Case::Kebab | Case::Lower | Case::Snake => result,
118	                    Case::Pascal | Case::NumberableCapital => Case::Pascal,
119	                    Case::Upper if !strict || !has_consecutive_uppercase => Case::Pascal,
120	                    _ => return Case::Unknown,
121	                },
122	                _ if current_char.is_numeric() => result,
123	                _ if current_char.is_alphabetic() => match result {
124	                    Case::Uni => Case::Uni,
125	                    _ => return Case::Unknown,
126	                },
127	                _ => return Case::Unknown,
128	            };
129	            previous_char = current_char;
130	        }
131	        result
132	    }
